ALTER TABLE public.company_settings ADD COLUMN technical_structure jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE public.technician_locations (user_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES public.companies(id), shift_id uuid NOT NULL REFERENCES public.shifts(id), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy double precision NOT NULL CHECK(accuracy>=0), speed double precision, recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.technician_locations TO authenticated;
GRANT ALL ON public.technician_locations TO service_role;
ALTER TABLE public.technician_locations ENABLE ROW LEVEL SECURITY;
CREATE POLICY location_read ON public.technician_locations FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (user_id=auth.uid() OR public.my_role() IN ('admin','superuser','supervisor')) AND EXISTS(SELECT 1 FROM public.shifts s WHERE s.id=shift_id AND s.ended_at IS NULL));
CREATE POLICY location_insert ON public.technician_locations FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND user_id=auth.uid() AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.shifts s WHERE s.id=shift_id AND s.user_id=auth.uid() AND s.shift_type='shift' AND s.ended_at IS NULL));
CREATE POLICY location_update ON public.technician_locations FOR UPDATE TO authenticated USING(company_id=public.current_company_id() AND user_id=auth.uid() AND public.member_is_active(auth.uid())) WITH CHECK(company_id=public.current_company_id() AND user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.shifts s WHERE s.id=shift_id AND s.user_id=auth.uid() AND s.shift_type='shift' AND s.ended_at IS NULL));
CREATE FUNCTION public.stamp_shift_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.recorded_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER stamp_shift_location BEFORE INSERT OR UPDATE ON public.technician_locations FOR EACH ROW EXECUTE FUNCTION public.stamp_shift_location();
CREATE TABLE public.technical_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),uploaded_by uuid NOT NULL DEFAULT auth.uid(),title text NOT NULL DEFAULT 'Field scan',file_path text NOT NULL UNIQUE,page_count integer NOT NULL DEFAULT 1 CHECK(page_count>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','archived')),restricted boolean NOT NULL DEFAULT false,classification jsonb NOT NULL DEFAULT '{}'::jsonb,content_tags text[] NOT NULL DEFAULT '{}',keywords text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',site_id uuid REFERENCES public.sites(id),asset_id uuid REFERENCES public.assets(id),pages jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.technical_documents TO authenticated;
GRANT ALL ON public.technical_documents TO service_role;
ALTER TABLE public.technical_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY technical_read ON public.technical_documents FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (public.my_role() IN ('superuser','supervisor','admin') OR (status='approved' AND NOT restricted) OR (uploaded_by=auth.uid() AND status='pending' AND NOT restricted)));
CREATE POLICY technical_insert ON public.technical_documents FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND (public.my_role() IN ('superuser','supervisor') OR (status='pending' AND NOT restricted)));
CREATE POLICY technical_update ON public.technical_documents FOR UPDATE TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.my_role() IN ('superuser','supervisor')) WITH CHECK(company_id=public.current_company_id() AND public.my_role() IN ('superuser','supervisor'));
CREATE POLICY technical_delete ON public.technical_documents FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND public.my_role()='superuser');
CREATE FUNCTION public.guard_technical_document() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.company_module_access(NEW.company_id,'core') THEN RAISE EXCEPTION 'Company workspace is read-only'; END IF;
 IF NEW.file_path<>NEW.company_id::text||'/'||NEW.uploaded_by::text||'/'||NEW.id::text||'.pdf' THEN RAISE EXCEPTION 'Invalid document path'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by OR NEW.file_path IS DISTINCT FROM OLD.file_path) THEN RAISE EXCEPTION 'Document identity cannot change'; END IF;
 IF NEW.site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites s WHERE s.id=NEW.site_id AND s.company_id=NEW.company_id) THEN RAISE EXCEPTION 'Invalid site'; END IF;
 IF NEW.asset_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.assets a WHERE a.id=NEW.asset_id AND a.company_id=NEW.company_id AND (NEW.site_id IS NULL OR a.site_id=NEW.site_id)) THEN RAISE EXCEPTION 'Invalid equipment'; END IF;
 NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER guard_technical_document BEFORE INSERT OR UPDATE ON public.technical_documents FOR EACH ROW EXECUTE FUNCTION public.guard_technical_document();
CREATE TABLE public.jobsheet_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),jobsheet_id uuid NOT NULL REFERENCES public.job_sheets(id) ON DELETE CASCADE,uploaded_by uuid NOT NULL DEFAULT auth.uid(),file_path text NOT NULL UNIQUE,page_count integer NOT NULL DEFAULT 1 CHECK(page_count>0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.jobsheet_receipts TO authenticated;
GRANT ALL ON public.jobsheet_receipts TO service_role;
ALTER TABLE public.jobsheet_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_read ON public.jobsheet_receipts FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_id));
CREATE POLICY receipt_insert ON public.jobsheet_receipts FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND file_path=company_id::text||'/'||jobsheet_id::text||'/'||id::text||'.pdf' AND EXISTS(SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_id AND j.company_id=company_id AND j.status<>'completed'));
CREATE POLICY receipt_delete ON public.jobsheet_receipts FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND public.my_role() IN ('superuser','admin','supervisor') AND EXISTS(SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_id AND j.status<>'completed'));
CREATE TRIGGER receipt_commercial_guard BEFORE INSERT OR DELETE ON public.jobsheet_receipts FOR EACH ROW EXECUTE FUNCTION public.guard_parent_sheet_write();
CREATE POLICY technical_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='technical-library' AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.technical_documents d WHERE d.file_path=name));
CREATE POLICY technical_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='technical-library' AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.technical_documents d WHERE d.file_path=name AND d.uploaded_by=auth.uid() AND d.status='pending'));
CREATE POLICY receipt_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='job-receipts' AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.jobsheet_receipts r WHERE r.file_path=name));
CREATE POLICY receipt_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='job-receipts' AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.jobsheet_receipts r JOIN public.job_sheets j ON j.id=r.jobsheet_id WHERE r.file_path=name AND r.uploaded_by=auth.uid() AND j.status<>'completed'));
CREATE INDEX technical_documents_tenant_status ON public.technical_documents(company_id,status);
CREATE INDEX jobsheet_receipts_sheet ON public.jobsheet_receipts(jobsheet_id);
CREATE FUNCTION public.search_technical_documents(_query text DEFAULT '',_site uuid DEFAULT NULL,_asset uuid DEFAULT NULL,_status text DEFAULT 'approved') RETURNS SETOF public.technical_documents LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT d.* FROM public.technical_documents d WHERE (_status='' OR d.status=_status) AND (_site IS NULL OR d.site_id=_site OR d.site_id IS NULL) AND (_asset IS NULL OR d.asset_id=_asset OR d.asset_id IS NULL) AND (_query='' OR lower(concat_ws(' ',d.title,d.keywords,d.notes,d.classification::text,array_to_string(d.content_tags,' '),d.pages::text)) LIKE '%'||lower(left(_query,200))||'%') ORDER BY d.updated_at DESC LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.search_technical_documents(text,uuid,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.search_technical_documents(text,uuid,uuid,text) TO authenticated;